shes jsonb:='{}'; hash_all text; t record;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('DOCUMENTS.NO_DEBT_LETTER_DEFAULT_BUSINESS_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='DOCUMENTS' AND config_key='NO_DEBT_LETTER_DEFAULT_BUSINESS_DAYS' AND hecho='ar_letter_default_sla') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT DOCUMENTS.NO_DEBT_LETTER_DEFAULT_BUSINESS_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.LETTER_EXPLANATION_MAX_CHARS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='LETTER_EXPLANATION_MAX_CHARS' AND hecho='ar_letter_max_chars') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.LETTER_EXPLANATION_MAX_CHARS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.LETTER_EXPLANATION_MOBILE_LINES') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='LETTER_EXPLANATION_MOBILE_LINES' AND hecho='ar_letter_mobile_lines') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.LETTER_EXPLANATION_MOBILE_LINES'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.LETTER_EXPLANATION_DESKTOP_LINES') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='LETTER_EXPLANATION_DESKTOP_LINES' AND hecho='ar_letter_desktop_lines') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.LETTER_EXPLANATION_DESKTOP_LINES'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.RECUPERA_PROGRESS_Q1') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='RECUPERA_PROGRESS_Q1' AND hecho='ar_progress_q1') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.RECUPERA_PROGRESS_Q1'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.RECUPERA_PROGRESS_Q2') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='RECUPERA_PROGRESS_Q2' AND hecho='ar_progress_q2') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.RECUPERA_PROGRESS_Q2'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.RECUPERA_PROGRESS_Q3') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='RECUPERA_PROGRESS_Q3' AND hecho='ar_progress_q3') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.RECUPERA_PROGRESS_Q3'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.RECUPERA_PROGRESS_Q4') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='RECUPERA_PROGRESS_Q4' AND hecho='ar_progress_q4') THEN RAISE EXCEPTION 'S22AR_PARAM_PREFLIGHT CLIENT.RECUPERA_PROGRESS_Q4'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AR_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AR_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AR_HASH_ALL %',hash_all;
END $ar$;
COMMIT;
